"""Render documentation from the catalog. Generated files are committed and checked for freshness."""

from __future__ import annotations

from archfit.graph import availability_ceiling, incoming
from archfit.model import Catalog, Component, Edge
from archfit.rules import all_rules

HEADER = "<!-- Generated by `archfit docs` from catalog/platform.toml. Do not edit by hand. -->\n\n"


def _row(cells: list[str]) -> str:
    return "| " + " | ".join(cells) + " |"


def _table(head: list[str], rows: list[list[str]]) -> str:
    lines = [_row(head), _row(["---"] * len(head)), *(_row(r) for r in rows)]
    return "\n".join(lines) + "\n"


def _ordered(c: Catalog) -> list[Component]:
    return sorted(c.components.values(), key=lambda x: (c.layers[x.layer].order, x.tier, x.id))


def components_md(c: Catalog) -> str:
    rows = []
    for x in _ordered(c):
        impl = f"[repo]({x.reference_impl})" if x.reference_impl else ""
        rows.append(
            [
                f"`{x.id}`",
                c.layers[x.layer].name,
                str(x.tier),
                x.owner,
                x.data_max_class,
                f"{x.availability:g}%",
                "" if x.rto_minutes is None else str(x.rto_minutes),
                x.description,
                impl,
            ]
        )
    head = [
        "Component",
        "Layer",
        "Tier",
        "Owner",
        "Max data class",
        "Availability target",
        "RTO (min)",
        "Purpose",
        "Reference implementation",
    ]
    return (
        HEADER + f"# Components\n\n{len(c.components)} components in {len(c.layers)} layers. "
        "Tier 1 is business-critical, tier 3 can wait for the next working day. Availability figures "
        "are design targets, not measurements.\n\n" + _table(head, rows)
    )


def _node(x: Component) -> str:
    return x.id.replace("-", "_")


def _edge_line(e: Edge) -> list[str]:
    a, b = e.source.replace("-", "_"), e.target.replace("-", "_")
    if e.kind == "async":
        line = f"  {a} -.-> {b}"
    elif e.kind == "library":
        line = f"  {a} ==> {b}"
    elif e.optional:
        line = f"  {a} -->|optional| {b}"
    else:
        line = f"  {a} --> {b}"
    out = [line]
    if e.fallback:
        out.append(f"  {a} -. fallback .-> {e.fallback.replace('-', '_')}")
    return out


def critical_path(c: Catalog, start: str) -> set[str]:
    """Components a request entering at ``start`` hard-depends on (synchronous, not optional)."""
    seen: set[str] = set()
    todo = [start]
    while todo:
        cur = todo.pop()
        if cur in seen or cur not in c.components:
            continue
        seen.add(cur)
        for e in c.components[cur].depends_on:
            if e.kind == "sync" and not e.optional:
                todo.append(e.target)
                if e.fallback:
                    todo.append(e.fallback)
    return seen


def dependencies_md(c: Catalog) -> str:
    out = [HEADER, "# Dependencies\n\n"]
    out.append(
        "## By layer\n\nEach arrow is the number of dependencies from one layer to another.\n\n"
    )
    counts: dict[tuple[str, str], int] = {}
    for e in c.edges():
        if e.target in c.components:
            a, b = c.components[e.source].layer, c.components[e.target].layer
            if a != b:
                counts[(a, b)] = counts.get((a, b), 0) + 1
    out.append("```mermaid\nflowchart TB\n")
    for lid in sorted(c.layers, key=lambda k: c.layers[k].order):
        out.append(f'  {lid}["{c.layers[lid].name}"]\n')
    for (a, b), n in sorted(counts.items()):
        out.append(f"  {a} -->|{n}| {b}\n")
    out.append("```\n\n")

    out.append(
        "## All components\n\nSolid arrow: synchronous call. Dotted: asynchronous. Thick: in-process "
        "library. `optional`: the request succeeds without it. `fallback`: used when the primary is down.\n\n"
    )
    out.append("```mermaid\nflowchart LR\n")
    for lid in sorted(c.layers, key=lambda k: c.layers[k].order):
        members = [x for x in _ordered(c) if x.layer == lid]
        if not members:
            continue
        out.append(f'  subgraph {lid}_g["{c.layers[lid].name}"]\n')
        for x in members:
            out.append(f'    {_node(x)}["{x.name}"]\n')
        out.append("  end\n")
    for x in _ordered(c):
        for e in x.depends_on:
            out.extend(line + "\n" for line in _edge_line(e))
    out.append("```\n\n")

    for x in _ordered(c):
        if not x.entrypoint or x.layer != "channels":
            continue
        path = critical_path(c, x.id)
        out.append(
            f"## Critical path of `{x.id}`\n\nEverything a request needs to be up, "
            f"{len(path)} components:\n\n```mermaid\nflowchart LR\n"
        )
        for cid in sorted(path):
            out.append(f'  {cid.replace("-", "_")}["{c.components[cid].name}"]\n')
        for cid in sorted(path):
            for e in c.components[cid].depends_on:
                if e.kind == "sync" and not e.optional and e.target in path:
                    out.append(f"  {cid.replace('-', '_')} --> {e.target.replace('-', '_')}\n")
                    if e.fallback and e.fallback in path:
                        out.append(
                            f"  {cid.replace('-', '_')} -. fallback .-> {e.fallback.replace('-', '_')}\n"
                        )
        out.append("```\n\n")
    return "".join(out)


def data_flows_md(c: Catalog) -> str:
    rows = []
    for e in sorted(c.edges(), key=lambda e: (-c.level(e.data), e.source, e.target)):
        target = c.components[e.target]
        zone = "external" if target.external else "internal"
        rows.append(
            [
                f"`{e.source}`",
                f"`{e.target}`",
                e.data,
                e.kind + (" (optional)" if e.optional else ""),
                target.data_max_class,
                zone,
                f"`{e.fallback}`" if e.fallback else "",
            ]
        )
    head = [
        "From",
        "To",
        "Data class carried",
        "Kind",
        "Target cleared for",
        "Target zone",
        "Fallback",
    ]
    external = sorted({e.target for e in c.edges() if c.components[e.target].external})
    egress = sorted(x.id for x in c.components.values() if x.egress)
    return (
        HEADER + "# Data flows\n\nEvery dependency with the classification of the data it carries. "
        "The fitness function `FIT006` fails the build if a flow carries data above what the target is cleared for.\n\n"
        f"Egress components (the only ones allowed to call external systems): {', '.join(f'`{x}`' for x in egress)}.\n"
        f"External systems: {', '.join(f'`{x}`' for x in external)}.\n\n" + _table(head, rows)
    )


def slo_register_md(c: Catalog) -> str:
    rows = []
    for x in _ordered(c):
        ceiling = availability_ceiling(c, x.id)
        hard = [e.target for e in x.depends_on if e.kind == "sync" and not e.optional]
        rows.append(
            [
                f"`{x.id}`",
                str(x.tier),
                f"{x.availability:g}%",
                f"{ceiling:.4f}%" if hard else "no hard dependencies",
                ", ".join(f"`{h}`" for h in hard),
            ]
        )
    head = ["Component", "Tier", "Target", "Ceiling from hard dependencies", "Hard dependencies"]
    return (
        HEADER
        + "# Availability register\n\nA component cannot reliably promise more than the product of "
        "the availability of the services it calls synchronously. With a fallback, the dependency is "
        "down only when both it and the fallback are down. `FIT005` fails the build when a target is "
        "above its ceiling.\n\nTargets are design values for the reference, not measurements.\n\n"
        + _table(head, rows)
    )


def ownership_md(c: Catalog) -> str:
    rows = []
    refs = incoming(c)
    for t in sorted(c.teams.values(), key=lambda t: t.id):
        owned = sorted(x.id for x in c.components.values() if x.owner == t.id)
        tier1 = sum(1 for i in owned if c.components[i].tier == 1)
        rows.append(
            [
                f"`{t.id}`",
                t.responsibility,
                f"`{t.contact}`",
                str(len(owned)),
                str(tier1),
                ", ".join(f"`{i}`" for i in owned),
            ]
        )
    head = ["Team", "Responsibility", "Contact", "Components", "Tier 1", "Owns"]
    users = sum(len(v) for v in refs.values())
    return (
        HEADER
        + f"# Ownership\n\n{users} dependency references across {len(c.components)} components.\n\n"
        + _table(head, rows)
    )


def rules_md() -> str:
    out = [
        HEADER,
        "# Fitness functions\n\nRun with `archfit check`. They fail the build when the design "
        "breaks one of its own rules.\n\n",
    ]
    rows = [[r.id, r.severity, r.title] for r in all_rules()]
    out.append(
        _table(
            ["ID", "Severity", "Rule"],
            [
                ["FIT001", "critical", "The catalog must match its schema"],
                ["FIT000", "high", "A waiver must not be past its expiry date"],
                *rows,
            ],
        )
    )
    for r in all_rules():
        out.append(
            f"\n## {r.id}: {r.title}\n\n**Severity:** {r.severity}\n\n**Why it matters.** {r.why}\n\n**How to fix it.** {r.fix}\n"
        )
    return "".join(out)


GENERATED = {
    "components.md": components_md,
    "dependencies.md": dependencies_md,
    "data-flows.md": data_flows_md,
    "slo-register.md": slo_register_md,
    "ownership.md": ownership_md,
}
